Definition SOBUF : Z := 7029536.
Definition stdoutA (j : Z) (MV : word -> option byte) : Prop :=
  rdn ASEGS MV (Z_to_bv 64 1422992) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 5))                       (* [comment removed for export] *)
